    '_content' => '<!DOCTYPE html>
<html lang="ru" itemscope itemtype="https://schema.org/WebPage">

<head>
    {include \'meta\'}
    {$_modx->resource.codecviz}
    {set $sliders = json_decode($_modx->resource.baner_img, true)}
    
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, sans-serif;
            background: #fff;
            color: #1a1a1a;
            overflow-x: hidden;
        }

        /* --- АНИМАЦИЯ REVEAL --- */
        @supports (animation-timeline: view()) {
            .reveal {
                opacity: 0;
                transform: translateY(80px) scale(0.9);
                filter: blur(10px);
                animation: revealAnim linear both;
                animation-timeline: view();
                animation-range-start: entry 20%;
                animation-range-end: entry 80%;
            }

            @keyframes revealAnim {
                from {
                    opacity: 0;
                    transform: translateY(80px) scale(0.9);
                    filter: blur(10px);
                }

                to {
                    opacity: 1;
                    transform: translateY(0) scale(1);
                    filter: blur(0);
                }
            }
        }

        @supports not (animation-timeline: view()) {
            .reveal {
                opacity: 1;
                transform: none;
                filter: none;
            }
        }

        .section-title {
            position: relative;
            display: inline-block;
            text-align: left;
        }

        .section-title::after {
            content: \'\';
            position: absolute;
            bottom: -8px;
            left: 0;
            width: 60px;
            height: 3px;
            background: linear-gradient(90deg, #3F5F3F, #d4a574);
            border-radius: 2px;
        }

        .text-center .section-title::after {
            left: 50%;
            transform: translateX(-50%);
        }

        .hero-slider {
            height: 100vh;
            min-height: 700px;
        }

        .hero-slide {
            position: relative;
            height: 100%;
        }

        .hero-slide img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to right, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.5) 50%, transparent 100%);
        }

        @keyframes ticker {
            0% {
                transform: translateX(0);
            }

            100% {
                transform: translateX(-50%);
            }
        }

        .animate-ticker {
            animation: ticker 35s linear infinite;
        }

        .timeline-line {
            position: absolute;
            left: 24px;
            top: 0;
            bottom: 0;
            width: 2px;
            background: linear-gradient(to bottom, #3F5F3F, #d4a574);
            z-index: 0;
        }

        @media (min-width: 768px) {
            .timeline-line {
                left: 50%;
                transform: translateX(-50%);
            }
        }

        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: #f1f1f1;
        }

        ::-webkit-scrollbar-thumb {
            background: #3F5F3F;
            border-radius: 4px;
        }

        /* Accessibility: увеличенные области прикосновения */
        .footer__social-social a,
        .abssocial a {
            min-width: 48px;
            min-height: 48px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 12px;
        }

        /* LCP: текст hero виден до загрузки Tailwind */
        .hero-slider h1 {
            font-size: clamp(1.875rem, 5vw, 3.75rem);
            font-weight: 800;
            line-height: 1.1;
            margin-bottom: 1.5rem;
        }

        /* Структура страницы: якоря не прячутся под фиксированным/верхним меню */
        section[id] {
            scroll-margin-top: 110px;
        }

        @media (max-width: 767px) {
            section[id] {
                scroll-margin-top: 80px;
            }
        }
        
        body {
            font-family: \'Inter\', sans-serif;
            background: #fff;
            color: #1a1a1a;
        }

        @keyframes marquee {
            0% {
                transform: translateX(0);
            }

            100% {
                transform: translateX(-50%);
            }
        }

        .animate-marquee {
            animation: marquee 30s linear infinite;
        }

        .service-popup li {
            margin: 4px 0;
            color: #4b5563;
            font-size: 14px;
        }

        /* Problems grid */
        .problem-card {
            background: #f8faf8;
            border: 1px solid #e5e7eb;
            border-radius: 12px;
            padding: 20px;
            text-align: center;
            transition: all 0.3s;
        }

        .problem-card:hover {
            border-color: #558255;
            transform: translateY(-3px);
        }

        /* FAQ accordion */
        .acor-container input[type="checkbox"] {
            display: none;
        }

        .acor-container .acor-body {
            max-height: 0;
            overflow: hidden;
            transition: all 0.3s ease;
        }

        .acor-container input[type="checkbox"]:checked+label+.acor-body {
            max-height: 300px;
            padding: 0 20px 20px;
        }

        .acor-container label {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 18px 20px;
            background: #f8f9fa;
            border-radius: 10px;
            cursor: pointer;
            border: 1px solid #e5e7eb;
            font-weight: 500;
        }

        .acor-container label:hover {
            background: #f0f0f0;
            border-color: #558255;
        }

        .acor-container label::after {
            content: \'+\';
            font-size: 22px;
            color: #558255;
            width: 30px;
            height: 30px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: #fff;
            border-radius: 50%;
            transition: all 0.3s;
        }

        .acor-container input[type="checkbox"]:checked+label::after {
            content: \'−\';
            background: #558255;
            color: #fff;
        }

        /* Carousel styles */
        .hero-carousel .swiper-slide {
            height: 500px;
        }

        .hero-carousel .swiper-slide img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        @media (max-width: 768px) {
            .hero-carousel .swiper-slide {
                height: 400px;
            }
        }

        .swiper-button-next:after,
        .swiper-button-prev:after {
            font-size: inherit;
        }

        .swiper-pagination-bullet-active {
            background: #95dd95 !important;
        }

        .swiper-pagination-bullet {
            background: var(--swiper-pagination-bullet-inactive-color, #ffffff);
        }

        /* Hero Slider Styles */
        .hero-swiper {
            height: 100%;
        }

        .hero-slide {
            position: relative;
            height: 100%;
        }

        .hero-slide img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to right, rgba(0, 0, 0, 0.65) 0%, rgba(0, 0, 0, 0.4) 50%, transparent 100%);
        }
    </style>
</head>

